-- James Jennings (profileID=10) — ENDORSEMENTS
-- Generated by endorsement_framework.py

-- STEP 1: PHRASE_ENDORSE rows for all James Jennings phrasings

SELECT p.argumentID, p.phrasingID, 10, 100, 1
FROM PHRASING p
WHERE p.coinedBy = 10
  AND NOT EXISTS (
    SELECT 1 FROM PHRASE_ENDORSE pe
    WHERE pe.profileID = 10 AND pe.argumentID = p.argumentID
  );

-- STEP 2: Endorsement chains (Because / Therefore / Rebuttal)

DELETE FROM ENDORSEMENT WHERE profileID=10 AND targArgID IN (80,88,89,90,94,104,107,120,123,130,134,140,145,175,226,229,230,266,267,288,291,297,324,326,327,328,329,331,333,349,350,383,400,412,414,428,460,461,462,476,484,485,546,547,548,549,554,555,560,561,600,609,611,615,616,617,618,651,652,658,659,777,844,972,1159,1160,1172,1177,1178,1179,1181,1197,1202,1229,1237,1275,1276,1345,1347,1385,1386,1410,1440);


-- STEP 3: Sync PHRASE_ENDORSE active flag with opinion acceptance

UPDATE PHRASE_ENDORSE pe
JOIN OPINION o ON pe.argumentID = o.argumentID AND o.profileID = 10
SET pe.active = o.acceptance
WHERE pe.profileID = 10;

SELECT 'Done: endorsements for profileID=10' AS status;